select lives_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'snapshot',current_setting('f5.snapshot')::jsonb)$$,'consulta integrada de extrato livro e saldos');
select is(public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'snapshot',current_setting('f5.snapshot')::jsonb)->'checklist'->>'bankPending','1','extrato inicialmente pendente');
select is(public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'snapshot',current_setting('f5.snapshot')::jsonb)->'checklist'->>'bookPending','2','bruto e taxa inicialmente pendentes');
select throws_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'import',jsonb_set(current_setting('f5.import')::jsonb,'{transactions,0,amount}','"9700"')||jsonb_build_object('id','ab720000-0000-4000-8000-000000000004','sourceHash',repeat('d',64)))$$,'22023',null,'FITID reapresentado com valor divergente é recusado');
select is(public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'import',current_setting('f5.import')::jsonb||jsonb_build_object('id','ab720000-0000-4000-8000-000000000005','sourceHash',repeat('e',64)))->>'duplicates','1','novo arquivo sobreposto reaproveita o FITID sem duplicar');
select throws_ok($$select public.finance_f5(current_setting('f4.org')::uuid,'cf700000-0000-4000-8000-000000000002','snapshot',current_setting('f5.snapshot')::jsonb)$$,'42501',null,'consulta não atravessa a conta da outra unidade');
select lives_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'ignore',jsonb_build_object('id','ab770000-0000-4000-8000-000000000001','transaction',current_setting('f5.bank'),'version',1,'ignored',true,'reason','Análise fictícia da possível duplicidade'))$$,'desconsideração explícita e versionada');
select is(public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'snapshot',current_setting('f5.snapshot')::jsonb)->'checklist'->>'ignored','1','desconsiderado permanece no checklist');
select throws_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'ignore',jsonb_build_object('id','ab770000-0000-4000-8000-000000000002','transaction',current_setting('f5.bank'),'version',1,'ignored',false,'reason','Tentativa fictícia com versão antiga'))$$,'40001',null,'versão antiga não sobrescreve tratamento');
select lives_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'ignore',jsonb_build_object('id','ab770000-0000-4000-8000-000000000003','transaction',current_setting('f5.bank'),'version',2,'ignored',false,'reason','Análise fictícia concluída para conciliação'))$$,'restauração preserva o histórico');
select set_config('f5.match',jsonb_build_object('id','ab730000-0000-4000-8000-000000000001','account','df700000-0000-4000-8000-000000000001','reason','Conferência fictícia do depósito e taxa','bank',jsonb_build_array(current_setting('f5.bank')),'book',jsonb_build_array('ab710000-0000-4000-8000-000000000001','ab710000-0000-4000-8000-000000000002'))::text,true);
select throws_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'match',current_setting('f5.match')::jsonb||jsonb_build_object('book',jsonb_build_array('ab710000-0000-4000-8000-000000000001')))$$,'22023',null,'bruto sozinho não corresponde ao líquido');
select lives_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'match',current_setting('f5.match')::jsonb)$$,'conciliação agrupa bruto e taxa sem duplicar');
select lives_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'match',current_setting('f5.match')::jsonb)$$,'confirmação repetida não cria vínculo duplicado');
select throws_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'match',current_setting('f5.match')::jsonb||'{"id":"ab730000-0000-4000-8000-000000000002"}')$$,'40001',null,'movimento já conciliado não pode ser reutilizado');
select is(public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'snapshot',current_setting('f5.snapshot')::jsonb)->'checklist'->>'reconciled','true','saldo e vínculos conferidos sem pendências');
