select is(private.finance_receipt_bank_status('af780000-0000-4000-8000-000000000004'),'reconciled','recebimento e taxa conciliados por evidências bancárias');
select is((select snapshot->>'state' from private.finance_digital_receipts where id='af780000-0000-4000-8000-000000000004'),'approved','conciliação não reescreve a prova do pagamento');
set local role authenticated;
select throws_ok($$select public.finance_f1(current_setting('f4.org')::uuid,array[current_setting('f4.unit')::uuid],'void',jsonb_build_object('id','ab710000-0000-4000-8000-000000000001','version',1,'reason','Tentativa fictícia sem desconciliar','date',current_setting('f5.day'),'requestId','ab740000-0000-4000-8000-000000000001'))$$,'22023',null,'estorno antigo não altera movimento conciliado');
select lives_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'close',jsonb_build_object('id','ab750000-0000-4000-8000-000000000001','through',current_setting('f5.end'),'expectedClosed','','reason','Fechamento fictício com todos os itens conferidos','allowPending',false))$$,'fechamento mensal registra checklist');
select throws_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'undo','{"id":"ab760000-0000-4000-8000-000000000001","group":"ab730000-0000-4000-8000-000000000001","reason":"Correção fictícia com mês fechado"}')$$,'22023',null,'mês fechado impede desfazer conciliação');
select lives_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'reopen',jsonb_build_object('id','ab750000-0000-4000-8000-000000000002','through',current_setting('f5.previous'),'expectedClosed',current_setting('f5.end'),'reason','Reabertura fictícia autorizada para correção','allowPending',false))$$,'administrador reabre com histórico');
select lives_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'undo','{"id":"ab760000-0000-4000-8000-000000000002","group":"ab730000-0000-4000-8000-000000000001","reason":"Correção fictícia após reabertura"}')$$,'desconciliação auditada preserva o vínculo anterior');
select is(public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'snapshot',current_setting('f5.snapshot')::jsonb)->'checklist'->>'bankPending','1','movimento volta a pendente');
