select is(private.finance_receipt_bank_status('af780000-0000-4000-8000-000000000004'),'pending','desconciliação reflete no acompanhamento do provedor');
set local role authenticated;
select throws_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'close',jsonb_build_object('id','ab750000-0000-4000-8000-000000000003','through',current_setting('f5.end'),'expectedClosed',current_setting('f5.previous'),'reason','Fechamento fictício não autorizado com pendências','allowPending',false))$$,'22023',null,'fechamento normal recusa pendências');
select lives_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'close',jsonb_build_object('id','ab750000-0000-4000-8000-000000000004','through',current_setting('f5.end'),'expectedClosed',current_setting('f5.previous'),'reason','Responsável assume ressalvas fictícias documentadas','allowPending',true))$$,'proprietário registra fechamento com ressalvas explícitas');
select is(public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'close',jsonb_build_object('id','ab750000-0000-4000-8000-000000000004','through',current_setting('f5.end'),'expectedClosed',current_setting('f5.previous'),'reason','Responsável assume ressalvas fictícias documentadas','allowPending',true))->>'reconciled','false','fechado com ressalvas não vira conciliado');
select throws_ok($$select public.finance_f5(current_setting('f4.org')::uuid,'cf700000-0000-4000-8000-000000000002','match',current_setting('f5.match')::jsonb)$$,'22023',null,'pedido de outra unidade não é reutilizado');
