select is((select count(*)::integer from private.finance_reconciliation_groups where organization_id=current_setting('f4.org')::uuid),1,'histórico da correspondência não foi apagado');
select is((select count(*)::integer from private.finance_f5_commands where organization_id=current_setting('f4.org')::uuid and action in('close','reopen')),3,'fechamentos e reabertura preservados sem duplicação');
select ok(not has_table_privilege('authenticated','private.finance_bank_transactions','select'),'tabela bancária não é exposta');
select ok(not has_function_privilege('anon','public.finance_f5(uuid,uuid,text,jsonb)','execute'),'visitante sem API financeira');
select ok(not has_function_privilege('authenticated','private.close_church_ledger_period(uuid,uuid,date)','execute'),'primitiva de fechamento não pode contornar checklist');
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) values('af700000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','f5-finance@example.test',now(),now(),now());
insert into public.organization_memberships(id,organization_id,user_id,role,status,default_unit_id) values('af790000-0000-4000-8000-000000000001',current_setting('f4.org')::uuid,'af700000-0000-4000-8000-000000000002','finance','active',current_setting('f4.unit')::uuid);
insert into public.membership_unit_access(membership_id,unit_id,access_level) values('af790000-0000-4000-8000-000000000001',current_setting('f4.unit')::uuid,'admin');
select set_config('request.jwt.claims','{"sub":"af700000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'snapshot',current_setting('f5.snapshot')::jsonb)$$,'financeiro autorizado consulta sua unidade');
select throws_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'reopen',jsonb_build_object('id','ab750000-0000-4000-8000-000000000009','through',current_setting('f5.previous'),'expectedClosed',current_setting('f5.end'),'reason','Tentativa fictícia de reabertura pelo financeiro','allowPending',false))$$,'42501',null,'financeiro não assume a reabertura administrativa');
select throws_ok($$select public.finance_f5(current_setting('f4.org')::uuid,'cf700000-0000-4000-8000-000000000002','snapshot',current_setting('f5.snapshot')::jsonb)$$,'42501',null,'financeiro sem concessão não lê outra unidade');
reset role;
update public.organization_memberships set status='suspended' where id='af790000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.finance_f5(current_setting('f4.org')::uuid,current_setting('f4.unit')::uuid,'snapshot',current_setting('f5.snapshot')::jsonb)$$,'42501',null,'suspensão é revalidada sem confiar no token antigo');
reset role;
select set_config('request.jwt.claims','{"sub":"af700000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select public.finance_f1(current_setting('f4.org')::uuid,array['cf700000-0000-4000-8000-000000000002']::uuid[],'catalog','{"id":"df700000-0000-4000-8000-000000000004","kind":"account","name":"Banco anterior fictício"}');
select public.finance_f1(current_setting('f4.org')::uuid,array['cf700000-0000-4000-8000-000000000002']::uuid[],'catalog','{"id":"df700000-0000-4000-8000-000000000005","kind":"category","name":"Recebimento anterior fictício","direction":"income"}');
select public.finance_f1(current_setting('f4.org')::uuid,array['cf700000-0000-4000-8000-000000000002']::uuid[],'entry',jsonb_build_object('id','ab710000-0000-4000-8000-000000000003','kind','income','amountCents','1000','description','Pendência de mês anterior fictícia','account','df700000-0000-4000-8000-000000000004','category','df700000-0000-4000-8000-000000000005','competence',current_setting('f5.previous'),'due',current_setting('f5.previous'),'paid',current_setting('f5.previous'),'method','pix'));
select is(public.finance_f5(current_setting('f4.org')::uuid,'cf700000-0000-4000-8000-000000000002','snapshot',current_setting('f5.snapshot')::jsonb||'{"account":""}')->'checklist'->>'bookPending','1','checklist acumula pendência anterior ao mês selecionado');
select throws_ok($$select public.finance_f5(current_setting('f4.org')::uuid,'cf700000-0000-4000-8000-000000000002','close',jsonb_build_object('id','ab750000-0000-4000-8000-000000000010','through',current_setting('f5.end'),'expectedClosed','','reason','Tentativa fictícia de ignorar pendência antiga','allowPending',false))$$,'22023',null,'fechar primeiro mês não oculta movimentos de meses anteriores');
reset role;
select * from finish();
rollback;
